// Charts for this page. Data comes from data.js, generated by scripts/site_assets.py from the
// bundled example planogram/report and the SKU-110K split sizes.
(function () {
  const D = window.SITE_DATA;

  Charts.define('facings', (el, C) => {
    const rows = D.facings;
    const x = rows.map(r => r.brand);
    const bar = (name, key, color) => ({
      type: 'bar', name, x, y: rows.map(r => r[key]), marker: { color },
      text: rows.map(r => r[key]), textposition: 'outside', cliponaxis: false, textfont: { color: C.ink },
      hovertemplate: '%{x}: %{y} facings<extra>' + name + '</extra>',
    });
    return {
      data: [bar('Planned', 'planned', C.violetDim), bar('On the shelf', 'observed', C.violet)],
      layout: { yaxis: { title: { text: 'facings' }, dtick: 1, range: [0, 6] }, xaxis: { tickangle: 0 }, legend: { y: -0.2 }, margin: { t: 14 } },
    };
  });

  Charts.define('shelves', (el, C) => {
    const rows = D.shelves;
    const y = rows.map(r => 'Shelf ' + r.shelf);
    const part = (name, key, color) => ({
      type: 'bar', orientation: 'h', name, y, x: rows.map(r => r[key]), marker: { color },
      hovertemplate: '%{y}: %{x} ' + name.toLowerCase() + '<extra></extra>',
    });
    return {
      data: [part('Matched', 'matched', C.green), part('Missing', 'missing', C.rose), part('Extra', 'extra', C.amber)],
      layout: { barmode: 'stack', yaxis: { autorange: 'reversed' }, xaxis: { title: { text: 'facings' }, dtick: 1 }, legend: { y: -0.24 } },
    };
  });

  Charts.define('share', (el, C) => {
    const entries = Object.entries(D.share);
    const narrow = el.clientWidth < 520;
    return {
      data: [{
        type: 'pie', hole: 0.62, labels: entries.map(e => e[0]), values: entries.map(e => e[1]),
        marker: { colors: [C.violet, C.cyan, C.green, C.amber, C.rose], line: { color: '#0d0d10', width: 2 } },
        textinfo: 'percent', textfont: { color: '#0b0b10', size: narrow ? 11 : 12 }, sort: false,
        hovertemplate: '%{label}: %{percent} of facings<extra></extra>',
      }],
      layout: {
        showlegend: true, legend: { orientation: narrow ? 'h' : 'v', x: narrow ? 0 : 1.02, y: narrow ? -0.1 : 0.5 },
        annotations: [{ text: `${Math.round(D.compliance * 100)}%<br><span style="font-size:11px">compliance</span>`, showarrow: false, font: { size: 22, color: C.ink } }],
      },
    };
  });

  Charts.define('splits', (el, C) => {
    const entries = Object.entries(D.splits);
    return {
      data: [{
        type: 'bar', x: entries.map(e => e[0]), y: entries.map(e => e[1]),
        marker: { color: [C.violet, C.cyan, C.green] }, text: entries.map(e => e[1].toLocaleString('en')),
        textposition: 'outside', cliponaxis: false, textfont: { color: C.ink },
        hovertemplate: '%{x}: %{y:,} images<extra></extra>',
      }],
      layout: { yaxis: { title: { text: 'images' }, separatethousands: true, range: [0, 9500] }, xaxis: { tickangle: 0 }, showlegend: false, margin: { t: 14 } },
    };
  });
})();
